def classify_questionnaire_parts(apps, schema_editor):
    WavePage = apps.get_model("pages", "WavePage")
    WaveModule = apps.get_model("waves", "WaveModule")

    db_alias = schema_editor.connection.alias

    pages = WavePage.objects.using(db_alias)
    modules = WaveModule.objects.using(db_alias)

    # 1. Fragebogenseiten klassifizieren
    episodes_pattern = r"[az][0-9]{3}$"

    n_episodes = pages.filter(
        pagename__regex=episodes_pattern
    ).update(questionnaire_part="episodes")

    n_core = pages.exclude(
        pagename__regex=episodes_pattern
    ).update(questionnaire_part="core")

    # 2. Module anhand ihrer Seiten klassifizieren
    n_core_modules = 0
    n_episodes_modules = 0

    for module in modules.all():
        parts = set(
            module.page_links.using(db_alias).values_list(
                "page__questionnaire_part",
                flat=True,
            )
        )

        if parts == {"core"}:
            module.questionnaire_part = "core"
            n_core_modules += 1

        elif parts == {"episodes"}:
            module.questionnaire_part = "episodes"
            n_episodes_modules += 1

        else:
            raise RuntimeError(
                f"Modul {module.pk} ({module.name}) "
                f"kann nicht eindeutig klassifiziert werden: {parts}"
            )

        module.save(
            using=db_alias,
            update_fields=["questionnaire_part"],
        )

    # 3. Ergebnisse ausgeben
    print("\nKlassifikation der Fragebogenteile:")
    print(f"  Core-Seiten: {n_core}")
    print(f"  Episodes-Seiten: {n_episodes}")
    print(f"  Core-Module: {n_core_modules}")
    print(f"  Episodes-Module: {n_episodes_modules}")

